import * as OurStringification from "../src/stringification";
import * as OurTypes from "../src/types";

test("Kind stringification round-trip Alpha", () => {
  const literal = OurTypes.Kind.Alpha;

  const text = OurStringification.mustKindToString(literal);
  expect(text).toStrictEqual("alpha");

  const nullableText = OurStringification.kindToString(literal);
  expect(nullableText).toStrictEqual("alpha");

  const parsed = OurStringification.kindFromString(text);
  expect(parsed).toStrictEqual(literal);
});

